/** How many ayahs of this edition are put right (for the credits): ayahs, not places. */
export function transliterationCorrectionCount(editionId: string): number {
  const list = TRANSLITERATION_CORRECTIONS[editionId];
  return list ? new Set(list.map(c => `${c[0]}:${c[1]}`)).size : 0;
}

/** One ayah as it is shown: as served, but for a listed fragment. */
export function correctTransliteration(
  editionId: string,
  surah: number,
  ayah: number,
  text: string,
): string {
  const list = TRANSLITERATION_CORRECTIONS[editionId];
  if (!list || !text) return text;
  let out = text;
  for (const [s, a, from, to] of list) {
    if (s === surah && a === ayah) out = out.replace(from, to);
  }
  return out;
}

/** A surah's lines, by ayah number, as they are shown. */
export function correctSurahTransliteration(
  editionId: string,
  surah: number,
  rows: Record<string, string>,
): Record<string, string> {
  const list = TRANSLITERATION_CORRECTIONS[editionId];
  if (!list || !list.some(c => c[0] === surah)) return rows;
  const out: Record<string, string> = { ...rows };
  for (const [s, a] of list) {
    const key = String(a);
    if (s === surah && out[key]) out[key] = correctTransliteration(editionId, surah, a, out[key]);
  }
  return out;
}
